; is the only scratch and is re-loaded from memory near the end
; (memory->R loads are byte loads, so R values stage via P6).
PUSH [P2+0]
POPF
MOV P6, [P2+8]
MOV R0, P6
MOV P6, [P2+10]
MOV R1, P6
MOV P6, [P2+12]
MOV R2, P6
MOV P6, [P2+14]
MOV R3, P6
MOV P6, [P2+16]
MOV R4, P6
MOV P6, [P2+18]
MOV R5, P6
MOV P6, [P2+20]
MOV R6, P6
MOV P6, [P2+22]
MOV R7, P6
MOV P6, [P2+24]
MOV R8, P6
MOV P6, [P2+26]
MOV R9, P6
MOV P0, [P2+28]
MOV P1, [P2+30]
MOV P3, [P2+34]
MOV P4, [P2+36]
MOV P6, [P2+38]
MOV P5, P6
MOV P6, [P2+42]
MOV P7, P6
MOV P6, [P2+40]
MOV FP, [P2+2]
MOV SP, [P2+4]
MOV P2, [P2+32]
RET
